const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const s = data[1];

let prefix = 0;
let answer = 0;
const count = new Map();
count.set(0, 1);

for (let i = 0; i < n; i++) {
    prefix += data[2 + i];
    const need = prefix - s;
    answer += count.get(need) || 0;
    count.set(prefix, (count.get(prefix) || 0) + 1);
}

console.log(answer);
